"""Editorial task history and structured task detail browser views."""

from __future__ import annotations

import json


def render_tasks_html(task_id: str | None = None) -> str:
    mode = "detail" if task_id else "list"
    task_literal = json.dumps(task_id)
    heading = "TASK\nDETAIL." if task_id else "TEST\nHISTORY."
    intro = (
        "需求、测试设计、评审依据与真实执行证据。"
        if task_id
        else "历史测试任务与执行结果。"
    )
    return f"""<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Req2Test · {'Task Detail' if task_id else 'Test History'}</title>
<style>
:root{{--paper:#f3f4f2;--blue-paper:#eef2f5;--ink:#12171f;--muted:#68717d;--blue:#5f7fa8;--line:rgba(18,23,31,.11);--dark:#0f1823;--success:#307a5a;--danger:#a84f52;--display:Inter,-apple-system,BlinkMacSystemFont,"Helvetica Neue",Arial,sans-serif;--zh:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif}}
*{{box-sizing:border-box}}body{{margin:0;background:var(--paper);color:var(--ink);font-family:var(--display);font-size:14px;-webkit-font-smoothing:antialiased}}a{{color:inherit;text-decoration:none}}button,input,select{{font:inherit}}.nav{{position:sticky;top:18px;z-index:20;width:min(calc(100% - 36px),1400px);height:58px;margin:18px auto 0;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:0 18px;border:1px solid rgba(255,255,255,.74);border-radius:16px;background:rgba(241,245,247,.82);box-shadow:0 14px 40px rgba(27,39,54,.08);backdrop-filter:blur(18px)}}.brand{{font-size:14px;font-weight:850;letter-spacing:.12em}}.brand b{{color:var(--blue)}}.links{{display:flex;gap:25px}}.links a{{position:relative;font-size:11px;font-weight:750;letter-spacing:.07em;white-space:nowrap}}.links a span{{font-family:var(--zh);font-size:10px;color:var(--muted)}}.links a.active:after{{content:"";position:absolute;left:0;right:0;bottom:-8px;height:1px;background:var(--ink)}}.account{{justify-self:end;display:flex;align-items:center;gap:14px;font-size:11px}}.account button{{border:0;background:none;font-weight:750;cursor:pointer}}main{{width:min(calc(100% - 64px),1400px);margin:auto;padding:100px 0 120px}}.hero{{display:grid;grid-template-columns:1.2fr .8fr;align-items:end;gap:60px;padding-bottom:42px;border-bottom:1px solid rgba(18,23,31,.2)}}.kicker,.section-label{{font-size:10px;font-weight:800;letter-spacing:.17em;color:var(--muted)}}h1{{margin:18px 0 0;white-space:pre-line;font-size:clamp(60px,7vw,100px);font-weight:500;line-height:.83;letter-spacing:-.06em}}.hero p{{justify-self:end;max-width:430px;margin:0;color:var(--muted);font-family:var(--zh);font-size:16px;line-height:1.75}}.filters{{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:12px;margin:34px 0 22px}}.filters input,.filters select{{min-width:0;padding:13px 12px;border:1px solid var(--line);background:rgba(255,255,255,.35);outline:0}}.filters button,.dark-button{{padding:13px 17px;border:0;background:var(--dark);color:white;font-size:10px;font-weight:800;letter-spacing:.08em;cursor:pointer}}.task-list{{border-top:1px solid rgba(18,23,31,.2)}}.task-row{{display:grid;grid-template-columns:minmax(260px,1.7fr) 110px 160px repeat(4,minmax(80px,.55fr));gap:22px;align-items:center;padding:25px 0;border-bottom:1px solid var(--line)}}.task-row:hover .row-title{{color:var(--blue)}}.row-title{{font-size:20px;font-weight:600;letter-spacing:-.025em}}.row-id,.row-time,.metric span{{display:block;margin-top:7px;color:var(--muted);font-size:9px;letter-spacing:.05em}}.state{{font-size:10px;font-weight:850;letter-spacing:.1em}}.state.completed,.pass{{color:var(--success)}}.state.failed,.fail{{color:var(--danger)}}.metric strong{{font-size:19px;font-weight:550}}.pager{{display:flex;justify-content:space-between;align-items:center;padding-top:28px;color:var(--muted);font-size:11px}}.pager button{{padding:9px 13px;border:1px solid var(--line);background:transparent;cursor:pointer}}.pager button:disabled{{opacity:.35}}.empty{{padding:70px 0;border-bottom:1px solid var(--line);color:var(--muted)}}.detail-meta{{display:grid;grid-template-columns:2fr repeat(3,1fr);margin:32px 0 70px;border-top:1px solid rgba(18,23,31,.2);border-bottom:1px solid var(--line)}}.fact{{padding:22px 24px 22px 0;border-right:1px solid var(--line)}}.fact:not(:first-child){{padding-left:24px}}.fact:last-child{{border-right:0}}.fact b{{display:block;font-size:15px;overflow-wrap:anywhere}}.fact span{{display:block;margin-top:10px;color:var(--muted);font-size:9px;letter-spacing:.08em}}.detail-section{{display:grid;grid-template-columns:250px 1fr;gap:45px;padding:45px 0;border-top:1px solid var(--line)}}.detail-section h2{{margin:8px 0 0;font-size:24px;font-weight:600;letter-spacing:-.035em}}.body-copy{{white-space:pre-wrap;color:#3f4853;line-height:1.75}}.case{{padding:24px 0;border-top:1px solid var(--line)}}.case:first-child{{padding-top:0;border:0}}.case-head{{display:flex;justify-content:space-between;gap:25px}}.case-id{{color:var(--blue);font-size:10px;font-weight:850;letter-spacing:.1em}}.case h3{{margin:9px 0;font-size:23px;letter-spacing:-.035em}}.case-meta{{color:var(--muted);font-size:10px}}.pill{{display:inline-block;padding:5px 8px;border:1px solid var(--line);border-radius:999px;font-size:8px;font-weight:850;letter-spacing:.07em}}.steps,.exec{{width:100%;margin-top:20px;border-collapse:collapse}}th,td{{padding:13px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}}th{{color:var(--muted);font-size:9px;letter-spacing:.08em}}td{{font-size:12px;line-height:1.55}}.score{{font-size:70px;font-weight:500;letter-spacing:-.06em}}.context{{padding:15px 0;border-bottom:1px solid var(--line);line-height:1.65}}.diagnosis{{padding:28px;background:var(--dark);color:#edf1f4}}.diagnosis+.diagnosis{{margin-top:12px}}.diagnosis h3{{margin:10px 0 18px;font-size:28px}}.diagnosis p{{color:#b8c2cc;line-height:1.7}}.no-failure{{padding:40px;border:1px solid var(--line);font-size:20px;letter-spacing:.04em}}details.raw{{margin-top:40px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}}details.raw summary{{padding:18px 0;font-size:10px;font-weight:800;cursor:pointer}}pre{{overflow:auto;max-height:520px;padding:20px;background:#e9edef;font-size:11px;line-height:1.6}}.exports{{display:flex;gap:9px;margin-top:25px}}.exports button{{padding:9px 12px;border:1px solid var(--line);background:transparent;font-size:9px;font-weight:800;cursor:pointer}}@media(max-width:1050px){{.links{{gap:12px}}.links a span{{display:none}}.task-row{{grid-template-columns:1.5fr 90px 130px repeat(2,80px)}}.task-row .metric:nth-last-child(-n+2){{display:none}}}}@media(max-width:800px){{.nav{{grid-template-columns:1fr auto}}.links{{display:none}}.account{{grid-column:2}}main{{width:calc(100% - 36px);padding-top:70px}}.hero{{grid-template-columns:1fr}}.hero p{{justify-self:start}}.filters{{grid-template-columns:1fr 1fr}}.task-row{{grid-template-columns:1fr 85px}}.task-row>*:not(:first-child):not(.state){{display:none}}.detail-meta,.detail-section{{grid-template-columns:1fr}}.fact{{border-right:0;border-bottom:1px solid var(--line);padding-left:0!important}}}}
</style></head><body><header class="nav"><a class="brand" href="/workbench">REQ<b>2</b>TEST</a><nav class="links"><a href="/workbench">WORKBENCH <span>/ 工作台</span></a><a class="active" href="/tasks">TASKS <span>/ 测试任务</span></a><a href="/knowledge">KNOWLEDGE <span>/ 知识库</span></a><a href="/workflow">HOW IT WORKS <span>/ 工作流程</span></a><a href="/system">SYSTEM <span>/ 系统状态</span></a></nav><div class="account"><a id="adminLink" style="display:none" href="/admin">ADMIN / 管理</a><span id="account"></span><button onclick="logout()">LOG OUT / 退出</button></div></header><main><section class="hero"><div><div class="kicker">REQ2TEST / PRODUCT CONSOLE</div><h1>{heading}</h1></div><p>{intro}</p></section><div id="content"><div class="empty">LOADING / 正在加载</div></div></main>
<script>
const MODE={json.dumps(mode)},TASK_ID={task_literal};let currentPage=1,currentDetail=null;
const esc=v=>String(v??'').replace(/[&<>\"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}}[c]));
const fmt=v=>v?new Date(v).toLocaleString('zh-CN',{{hour12:false}}):'—';
const percent=v=>v==null?'—':(Number(v)<=1?Math.round(Number(v)*100):Math.round(Number(v)))+'%';
async function authFetch(url,options){{const r=await fetch(url,options);if(r.status===401){{location.replace('/login?next='+encodeURIComponent(location.pathname+location.search));throw new Error('AUTH')}}return r}}
async function loadUser(){{const r=await authFetch('/api/v1/auth/me');if(r.ok){{const user=await r.json();document.getElementById('account').textContent=user.email;document.getElementById('adminLink').style.display=user.role==='admin'?'block':'none'}}}}
async function logout(){{await fetch('/api/v1/auth/logout',{{method:'POST'}});location.replace('/login')}}
function filterMarkup(){{return `<form class="filters" onsubmit="applyFilters(event)"><input id="keyword" placeholder="SEARCH TITLE OR REQUIREMENT / 搜索"><select id="status"><option value="">ALL STATUS / 全部状态</option><option>completed</option><option>failed</option><option>running</option><option>queued</option></select><input id="from" type="date" title="Created from"><input id="to" type="date" title="Created to"><button>FILTER →</button></form><div id="list"></div>`}}
function applyFilters(e){{e.preventDefault();currentPage=1;loadTasks()}}
async function loadTasks(page=currentPage){{currentPage=page;const q=new URLSearchParams({{page:String(page),page_size:'20'}}),keyword=document.getElementById('keyword')?.value,status=document.getElementById('status')?.value,from=document.getElementById('from')?.value,to=document.getElementById('to')?.value;if(keyword)q.set('keyword',keyword);if(status)q.set('status',status);if(from)q.set('created_from',new Date(from+'T00:00:00Z').toISOString());if(to)q.set('created_to',new Date(to+'T23:59:59Z').toISOString());const r=await authFetch('/api/v1/tasks?'+q);const d=await r.json();const list=document.getElementById('list');if(!d.items.length){{list.innerHTML='<div class="empty">NO TASKS FOUND / 暂无匹配任务</div>';return}}list.innerHTML='<div class="task-list">'+d.items.map(x=>`<a class="task-row" href="/tasks/${{x.id}}"><div><div class="row-title">${{esc(x.title)}}</div>${{x.summary.primary_failure_category?`<span class="failure-label">PRIMARY FAILURE · ${{esc(x.summary.primary_failure_category.replaceAll('_',' ').toUpperCase())}}</span>`:''}}<span class="row-id">${{esc(x.id)}}</span></div><div class="state ${{esc(x.status)}}">${{esc(x.status).toUpperCase()}}</div><div class="row-time">${{fmt(x.created_at)}}</div><div class="metric"><strong>${{x.summary.total_test_cases}}</strong><span>TEST CASES</span></div><div class="metric"><strong>${{x.summary.review_score??'—'}}</strong><span>REVIEW</span></div><div class="metric"><strong>${{percent(x.summary.http_pass_rate)}}</strong><span>HTTP PASS</span></div><div class="metric"><strong>${{x.summary.failure_analysis_count}}</strong><span>FAILURES</span></div></a>`).join('')+'</div>'+`<div class="pager"><span>${{d.total}} TASKS · PAGE ${{d.page}} / ${{d.pages||1}}</span><div><button ${{d.page<=1?'disabled':''}} onclick="loadTasks(${{d.page-1}})">← PREV</button> <button ${{d.page>=d.pages?'disabled':''}} onclick="loadTasks(${{d.page+1}})">NEXT →</button></div></div>`}}
function caseMarkup(c){{return `<article class="case"><div class="case-head"><div><div class="case-id">${{esc(c.case_id)}}</div><h3>${{esc(c.title)}}</h3><div class="case-meta">MODULE · ${{esc(c.module)}} &nbsp; REQUIREMENT · ${{esc(c.source_requirement)}}</div></div><div><span class="pill">${{esc(c.priority)}}</span> <span class="pill">${{esc(c.test_type)}}</span></div></div><div class="case-meta" style="margin-top:18px">PRECONDITIONS · ${{esc((c.preconditions||[]).join('；')||'—')}}</div><table class="steps"><thead><tr><th>NO.</th><th>ACTION / 操作</th><th>EXPECT / 预期</th></tr></thead><tbody>${{(c.steps||[]).map(s=>`<tr><td>${{String(s.order??'').padStart(2,'0')}}</td><td>${{esc(s.action)}}</td><td>${{esc(s.expected)}}</td></tr>`).join('')}}</tbody></table></article>`}}
function section(no,title,zh,body){{return `<section class="detail-section"><div><div class="section-label">${{no}}</div><h2>${{title}}<br><span style="font-family:var(--zh);font-size:13px;color:var(--muted)">${{zh}}</span></h2></div><div>${{body}}</div></section>`}}
function diagnosisMarkup(d){{const v=d.failure_analysis_v2||{{}},items=v.diagnoses||[];if(!items.length)return '<div class="no-failure">NO FAILURE DETECTED<br><small>0 DIAGNOSTIC ISSUES</small></div>';return `<div class="diagnosis-report"><div class="diagnosis-title">DIAGNOSIS<br>REPORT.</div>${{items.map(f=>`<article class="diagnosis v2"><div class="diagnosis-head"><span>${{esc(f.case_id||'TASK')}} / ${{esc(String(f.category).replaceAll('_',' '))}}</span><span>${{esc(String(f.confidence).toUpperCase())}} CONFIDENCE</span></div><h3>${{esc(f.probable_cause)}}</h3><div class="diagnosis-grid"><div><b>EVIDENCE</b>${{(f.evidence_summary||[]).map(x=>`<p>— ${{esc(x)}}</p>`).join('')}}</div><div><b>SUGGESTION</b><p>${{esc(f.suggestion)}}</p></div></div></article>`).join('')}}<details class="evidence-view" ontoggle="loadEvidence(this)"><summary>VIEW EVIDENCE / 查看详细证据</summary><div class="evidence-content">LOADING / 正在加载</div></details></div>`}}
function upgradeDiagnosis(d){{const sections=[...document.querySelectorAll('.detail-section')],target=sections.find(x=>x.querySelector('h2')?.textContent.includes('FAILURE ANALYSIS'));if(target)target.children[1].innerHTML=diagnosisMarkup(d)}}
async function loadEvidence(panel){{if(!panel.open||panel.dataset.loaded)return;panel.dataset.loaded='1';const target=panel.querySelector('.evidence-content'),r=await authFetch(`/api/v1/tasks/${{TASK_ID}}/diagnostics`);if(!r.ok){{target.textContent='EVIDENCE UNAVAILABLE';return}}const d=await r.json(),groups={{}};(d.evidence||[]).forEach(x=>(groups[x.evidence_type]??=[]).push(x));target.innerHTML=Object.entries(groups).map(([type,items])=>`<section class="evidence-group"><h4>${{esc(type.replaceAll('_',' ').toUpperCase())}}</h4>${{items.map(x=>`<details><summary>${{esc(x.stage)}} · ${{esc(x.summary)}}</summary><pre>${{esc(JSON.stringify(x.details,null,2))}}</pre></details>`).join('')}}</section>`).join('')||'<div>NO EVIDENCE</div>'}}
function renderDetail(d){{currentDetail=d;const t=d.task,e=d.execution||{{}},pytest=e.pytest_result;document.getElementById('content').innerHTML=`<div class="detail-meta"><div class="fact"><b>${{esc(t.title)}}</b><span>TASK TITLE</span></div><div class="fact"><b class="state ${{esc(t.status)}}">${{esc(t.status).toUpperCase()}}</b><span>STATUS</span></div><div class="fact"><b>${{fmt(t.created_at)}}</b><span>CREATED</span></div><div class="fact"><b>${{fmt(t.completed_at)}}</b><span>COMPLETED</span></div></div>${{section('01','REQUIREMENT','需求',`<div class="body-copy">${{esc(t.requirement_text)}}</div>`)}}${{section('02','TEST CASES','测试用例',(d.test_cases||[]).map(caseMarkup).join('')||'<div class="empty">NO TEST CASES</div>')}}${{section('03','AI REVIEW','AI 评审',`<div class="score">${{esc(d.review?.score??'—')}}<small style="font-size:18px"> / 100</small></div><p class="body-copy">COVERAGE · ${{percent(d.review?.coverage_rate)}}</p><p class="body-copy">${{esc([...(d.review?.issues||[]),...(d.review?.suggestions||[])].join('\\n')||'NO REVIEW NOTES')}}</p>`)}}${{section('04','RAG CONTEXT','检索上下文',(d.rag?.retrieved_context||[]).map((x,i)=>`<div class="context"><b>CONTEXT ${{String(i+1).padStart(2,'0')}}</b><br>${{esc(typeof x==='string'?x:JSON.stringify(x))}}</div>`).join('')||'<div class="empty">NO RAG CONTEXT</div>')}}${{section('05','EXECUTION','执行结果',`<table class="exec"><thead><tr><th>METHOD</th><th>PATH</th><th>EXPECTED</th><th>ACTUAL</th><th>DURATION</th><th>RESULT</th></tr></thead><tbody>${{(e.http_results||[]).map(x=>`<tr><td>${{esc(x.method)}}</td><td>${{esc((()=>{{try{{return new URL(x.url).pathname}}catch{{return x.url}}}})())}}</td><td>${{esc(x.expected_status)}}</td><td>${{esc(x.status_code)}}</td><td>${{esc(x.duration_ms??'—')}} ms</td><td class="${{x.passed?'pass':'fail'}}">${{x.passed?'PASS':'FAIL'}}</td></tr>`).join('')}}</tbody></table><p class="body-copy">PYTEST · ${{pytest?(pytest.passed?'PASS':'FAIL'):'NOT RUN'}}${{pytest?` · FAILED ${{pytest.failed_count??0}} · EXIT ${{pytest.exit_code??'—'}} · ${{pytest.duration_ms??'—'}} ms`:''}}</p>`)}}${{section('06','FAILURE ANALYSIS','失败归因',(d.failure_analysis||[]).map(f=>`<article class="diagnosis"><div class="section-label">${{esc(f.case_id)}} / ${{esc(f.category)}}</div><h3>${{esc(f.probable_cause)}}</h3><p><b>EVIDENCE</b><br>${{esc((f.evidence||[]).join('；')||'—')}}</p><p><b>SUGGESTION</b><br>${{esc(f.suggestion||'—')}}</p></article>`).join('')||'<div class="no-failure">NO FAILURE DETECTED</div>')}}<div class="exports"><button onclick="exportDetail('md')">EXPORT MARKDOWN</button><button onclick="exportDetail('csv')">EXPORT CSV</button><button onclick="exportDetail('json')">EXPORT JSON</button></div><details class="raw"><summary>VIEW RAW JSON / 查看原始 JSON</summary><pre>${{esc(JSON.stringify(d.raw_payload,null,2))}}</pre></details>`}}
async function loadDetail(){{const r=await authFetch('/api/v1/tasks/'+TASK_ID);if(r.status===404){{document.getElementById('content').innerHTML='<div class="empty">TASK NOT FOUND / 任务不存在或无权访问</div>';return}}const d=await r.json();renderDetail(d);upgradeDiagnosis(d)}}
function blob(text,type,name){{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{{type}}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}}function csv(v){{return `"${{String(v??'').replaceAll('"','""')}}"`}}function exportDetail(type){{const d=currentDetail;if(!d)return;if(type==='json')blob(JSON.stringify(d.raw_payload,null,2),'application/json','req2test-task.json');if(type==='md')blob(`# ${{d.task.title}}\n\n${{d.task.requirement_text}}\n\n`+(d.test_cases||[]).map(c=>`## ${{c.case_id}} ${{c.title}}`).join('\\n\\n'),'text/markdown','req2test-task.md');if(type==='csv')blob('\ufeff'+[['case_id','module','title','priority','type'],...(d.test_cases||[]).map(c=>[c.case_id,c.module,c.title,c.priority,c.test_type])].map(r=>r.map(csv).join(',')).join('\\n'),'text/csv','req2test-task.csv')}}
loadUser();if(MODE==='list'){{document.getElementById('content').innerHTML=filterMarkup();loadTasks()}}else loadDetail();
</script></body></html>""".replace(
        "</style></head>",
        "</style><style>.nav{grid-template-columns:auto 1fr auto}"
        ".links{justify-self:center}.account>span{max-width:180px;overflow:hidden;"
        "text-overflow:ellipsis;white-space:nowrap}.account button,.account a{white-space:nowrap}"
        ".diagnosis-report{display:grid;gap:14px}.diagnosis-title{font-size:clamp(40px,5vw,70px);line-height:.86;letter-spacing:-.055em;margin-bottom:18px}"
        ".diagnosis.v2{margin:0}.diagnosis-head{display:flex;justify-content:space-between;gap:20px;font-size:10px;font-weight:800;letter-spacing:.1em;color:#9fb0c0}"
        ".diagnosis-grid{display:grid;grid-template-columns:1fr 1fr;gap:34px;border-top:1px solid rgba(255,255,255,.15);padding-top:18px}"
        ".diagnosis-grid b{font-size:9px;letter-spacing:.12em}.evidence-view{margin-top:10px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}"
        ".evidence-view>summary{padding:18px 0;font-size:10px;font-weight:800;letter-spacing:.09em;cursor:pointer}.evidence-content{padding-bottom:25px}"
        ".evidence-group{padding:18px 0;border-top:1px solid var(--line)}.evidence-group h4{margin:0 0 12px;font-size:11px;letter-spacing:.1em}"
        ".evidence-group details summary{padding:9px 0;cursor:pointer;color:var(--muted)}.evidence-group pre{max-height:300px;margin:8px 0}"
        ".no-failure small{display:block;margin-top:10px;color:var(--muted);font-size:10px}@media(max-width:800px){.diagnosis-grid{grid-template-columns:1fr}}"
        ".failure-label{display:block;margin-top:7px;color:var(--danger);font-size:9px;font-weight:800;letter-spacing:.08em}"
        "</style></head>",
    )
